class Solution {
public:
    bool canVisitAllRooms(vector<vector<int>>& rooms) {
        int n = rooms.size();
        vector<int> seen(n, 0);
        stack<int> st;
        st.push(0);
        seen[0] = 2;
        while (!st.empty()) {
            int u = st.top();
            st.pop();
            for (int v : rooms[u]) {
                if (!seen[v]) {
                    seen[v] = 2;
                    st.push(v);
                }
            }
        }
        for (int s : seen) {
            if (!s) return false;
        }
        return true;
    }
};
